#include <iostream>
#include <cmath>
#include <iomanip>

int main() {
    // Section 1: Divisibility tests
    int num = 0;
    if (!(std::cin >> num)) return 0;
    bool div5 = (num % 5 == 0);
    bool div6 = (num % 6 == 0);

    std::cout << std::boolalpha;
    std::cout << "Is " << num << " divisible by 5 and 6? " << (div5 && div6) << "\n";
    std::cout << "Is " << num << " divisible by 5 or 6? " << (div5 || div6) << "\n";
    std::cout << "Is " << num << " divisible by 5 or 6, but not both? " << (div5 != div6) << "\n";

    // Section 2: Point in right triangle with vertices (0,0), (200,0), (0,100)
    double px = 0.0, py = 0.0;
    if (std::cin >> px >> py) {
        // Hypotenuse line: -0.5 * x + 100
        if (px >= 0.0 && px <= 200.0 && py >= 0.0 && py <= (-0.5 * px + 100.0)) {
            std::cout << "The point is in the triangle\n";
        } else {
            std::cout << "The point is not in the triangle\n";
        }
    }
    return 0;
}

#include <iostream>

int main() {
    // Directed line orientation check
    double x0 = 0, y0 = 0, x1 = 0, y1 = 0, x2 = 0, y2 = 0;
    if (std::cin >> x0 >> y0 >> x1 >> y1 >> x2 >> y2) {
        double cross_product = (x1 - x0) * (y2 - y0) - (x2 - x0) * (y1 - y0);
        if (cross_product > 0.0) {
            std::cout << "p2 is on the left side of the line\n";
        } else if (cross_product == 0.0) {
            std::cout << "p2 is on the same line\n";
        } else {
            std::cout << "p2 is on the right side of the line\n";
        }
    }

    // Compare costs
    double w1 = 0, p1 = 0, w2 = 0, p2 = 0;
    if (std::cin >> w1 >> p1 >> w2 >> p2) {
        double unit1 = p1 / w1;
        double unit2 = p2 / w2;
        if (unit1 < unit2) {
            std::cout << "Package 1 has a better price.\n";
        } else if (unit2 < unit1) {
            std::cout << "Package 2 has a better price.\n";
        } else {
            std::cout << "Two packages have the same price.\n";
        }
    }
    return 0;
}
